    observe: function(){
        if (this.periodObj() != undefined && this.periodObj().pk != undefined && this.periodObj().pk != ''){
            var cmpStatus = this.getStatusAction();
            var cmpPrevPeriod = this.getPrevPeriodAction();
            var cmpNextPeriod = this.getNextPeriodAction();

            cmpStatus.enable();
            this._period.previous_period? cmpPrevPeriod.enable(): cmpPrevPeriod.disable();
            this._period.next_period? cmpNextPeriod.enable(): cmpNextPeriod.disable();
        }
        else{
            var cmpStatus = this.getStatusAction();
            var cmpPrevPeriod = this.getPrevPeriodAction();
            var cmpNextPeriod = this.getNextPeriodAction();

            cmpStatus.disable();
            cmpPrevPeriod.disable();
            cmpNextPeriod.disable();
        }
    },

    periodObj: function(value, dispatch){
        dispatch = core.nullValue(dispatch, true);

        if(value !== undefined){
            this._period = value;

            if(dispatch) this.observe();
        }
        else
            return this._period;
    },

    payrollTypeObj: function(value, dispatch){
        dispatch = core.nullValue(dispatch, true);

        if(value !== undefined){
            this._payrollType = value;

            if(dispatch) this.observe();
        }
        else
            return this._payrollType;
    },

    payrollComplementObj: function(value, dispatch){
        dispatch = core.nullValue(dispatch, true);

        if(value !== undefined){
            this._payrollComplement = value;

            if(dispatch) this.observe();
        }
        else
            return this._payrollComplement;
    },

    changeStatusFolha: function(statusType){
        var msg = false;

        if(statusType == 3)
            msg = 'Primeiro cheque se existem pendencias para esta folha, pois, ' +
                  'todas as pendencias de validação da folha ' + this.folha.description + ' serão aprovados por você.</br></br>' +
                  'Tem certeza que deseja mudar o status da folha de pagamento para fechado?';
        else
            msg = 'Tem certeza que deseja mudar o status da folha ' + this.folha.description + '?';

        Ext.Msg.show({
            title: 'Status da Folha de Pagamento',
            msg: msg,
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            fn: function(b) {

                if(b == 'no') return;

                Ext.Ajax.request({
                    url: toolkit.util.Normalize.controller_action(
                        'GFPLancador',
                        'update_status_folha'
                    ),
                    params: {
                        pk: this.folha.pk,
                        status: statusType
                    },
                    success: function(request) {
                        var obj = Ext.decode(request.responseText);

                        if(obj.success){
                            this.folha = obj.folha;
                            this.refreshContraCheque();
                        }
                        else alert(obj.message);
                    },
                    scope: this
                })
            },
            scope: this
        });
    },

    nextPeriod: function(){
        if(this.periodObj() && this.periodObj().next_period){
            var periodField = this.getPeriodField();
            periodField.setValue(this.periodObj().next_period);
        }
    },

    previousPeriod: function(){
        if(this.periodObj() && this.periodObj().previous_period){
            var periodField = this.getPeriodField();
            periodField.setValue(this.periodObj().previous_period);
        }
    },

