    _updateRow: function(idx, pk){
        var selRec = this.getSelectionModel().getSelected()
        if(selRec && selRec.data.pk != pk)
            this.getSelectionModel().deselectRow(idx);
        this.getStore().load({
            params: this.getStore().lastOptions.params,
            callback: function(r, opt, success){
                var newRec =  this.getStore().getAt(idx);
                if(pk && pk == newRec.get('pk'))
                    this.getSelectionModel().selectRow(idx);
            },
            scope: this
        });
    },

    dependentsWindow: function(){
        var sel = this.getSelectionModel().getSelected();
        if(sel){
            new rh.dependente.DependenteManageWindow({
                servidor: sel.data.servidor,
            }).show();
        }else
            Ext.Msg.show({
                'title': 'Dependentes',
                'msg': 'Selecione um contracheque primeiro!',
                'buttons': Ext.Msg.OK,
                'icon': Ext.Msg.WARN
            });
    },

    executeActionPaycheck: function(action, id, idx, msg){
        var v_id = id, v_idx = idx;
        var rMask = new Ext.LoadMask(this.ownerCt.getEl(), {msg: msg? msg: 'Aguarde...'});
        rMask.show();
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action('GFPPayCheck', action),
            params: { paycheck: id},
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                rMask.hide();
                if(!obj.success) {
                    Ext.MessageBox.show({
                       title: 'Erro',
                       msg: obj.message,
                       buttons: Ext.MessageBox.OK,
                       icon: Ext.MessageBox.ERROR
                    })
                }else{
                    if(obj.changed){
                        this._updateRow(v_idx, obj.instance.pk);
                    }else{
                        Ext.MessageBox.show({
                           title: 'Informação',
                           msg: obj.message,
                           buttons: Ext.MessageBox.OK,
                           icon: Ext.MessageBox.INFO
                        });
                    }
                }

            },
            failure: function() {
                rMask.hide();
                Ext.MessageBox.show({
                   title: 'Erro',
                   msg: 'Ocorreu um erro inesperado',
                   buttons: Ext.MessageBox.OK,
                   icon: Ext.MessageBox.ERROR
                });
            },
            scope: this,
        });
    },

    messageWindow: function(index){
        var paycheck = this.getStore().getAt(index).data;

        new rh.gfp.payroll.PayrollMessageWindow({
            action: (paycheck.message ? 'update' : 'create'),
            values: 'remote',
            oId: paycheck.message,
            params: {
                paycheck: paycheck.pk,
            },
            callback: {
                success: {
                    scope: this,
                    fn: function(args) {
                        var opts = this.getStore().lastOptions;
                        Ext.Msg.show({
                            icon: Ext.Msg.INFO,
                            msg: 'Mensagem de contracheque atualizada com sucesso!',
                            buttons: Ext.Msg.OK
                        });
                        this.getStore().load(opts);
                    }
                }
            },
        }).show();
    },

    confirmRescission: function(index) {
        var sel = this.getSelectionModel().getSelected();
        if(sel){
            var paycheck = sel.data;
            Ext.Msg.show({
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                msg: 'Tem certeza que deseja adicionar os eventos de rescisão?',
                scope: this,
                fn: function(b) {
                    if(b == 'no') return;
                    var rMask = new Ext.LoadMask(this.ownerCt.getEl(), {msg: 'Aguarde aplicação do modelo!'});
                    rMask.show();
                    Ext.Ajax.request({
                        url: toolkit.util.Normalize.controller_action('GFPPayCheck', 'apply_model'),
                        params: {
                            paycheck: paycheck.pk,
                            model: 'rescisao'
                        },
                        success: function(request) {
                            var obj = Ext.decode(request.responseText);
                            rMask.hide();
                            if(!obj.success){
                                Ext.Msg.show({
                                    icon: Ext.Msg.ERROR,
                                    msg: obj.message,
                                    buttons: Ext.Msg.OK
                                });
                            }else{
                                this._updateRow(index, paycheck.pk);
                            }
                        },
                        failure: function(request) {
                            rMask.hide();
                            alert('Erro processando o cálculo de rescisão.')
                        },
                        scope: this
                    });
                }
            });
        }else
            Ext.Msg.show({
                'title': 'Dependentes',
                'msg': 'Selecione um contracheque primeiro!',
                'buttons': Ext.Msg.OK,
                'icon': Ext.Msg.WARN
            });
    },

